/** A synthetic SELL plan for an agent (one shape for every agent: the vetoes, not the levels, are under test). */
export const planOf = (id) => ({ agent: id, setup: "fixture setup", at_level: true, entry: 100, entry_note: "at the zone", stop: 102, stop_note: "beyond the zone", risk: 2, tp1: 97, tp1_note: "the next key zone", tp2: 95, tp2_note: "the zone after", progressive_stop: 100, rrr: { tp1: 1.5, tp2: 2.5 } });
/** The council's SELL, as every block wanted it. */
export const ANSWER_SELL = Object.freeze({ stance: "SELL", bias: "BEARISH", confidence: 0.7, entry_type: "limit", target: "tp1" });
/** The quorum decide() reads for a block. */
export const quorumFrom = (row) => ({ bias: "BEARISH", score: -0.4, long_share: Math.round((1 - row.share) * 100) / 100, short_share: row.share, neutral_share: 0 });
/** The guards decide() reads for a block (both sides allowed; each speaker's plan; the consensus, the arm, the confidences). */
export function guardsFrom(row, { rule = null } = {}) {
  const side = (list) => ({ side: "SELL", allowed: true, checks: [], plan: planOf("zone_pullback"), plans: Object.fromEntries(list.map(([id]) => [id, { status: "live", plan: planOf(id) }])), vetoes: [], cautions: [], supports: [], min_rrr: 0, target_rule: row.mode === "scalp" ? "nearest" : "rrr", tp1_min_r: 1, entry_trigger: { fired: false, source: null, note: "no confirmation", rooms_agree: [] } });
  const voices = (list) => list.map(([id, voice]) => ({ id, name: id, voice }));
  return {
    long: side(row.long), short: side(row.short), strategy_execution: true,
    consensus: { lean: row.lean, long: voices(row.long), short: voices(row.short) },
    ...(row.arm ? { arms: { mode: "live", version: 1, ids: row.arm, known: true } } : {}),
    agent_confidence: Object.fromEntries(Object.entries(row.conf).map(([id, [l, s]]) => [id, { long: l, short: s }])),
    ...(rule ? { veto_rule: rule } : {})
  };
}
